"""Fail-open runtime vocabulary. No network, learning or correction logic."""

import logging
import time
from pathlib import Path

from .utils import get_user_app_data_path
from .vocabulary_core import candidates, collect, merge, rank


class DynamicVocabularyManager:
    def __init__(self, config):
        self.config = dict(config)
        self.logger = logging.getLogger(__name__)
        self.last_report = {}

    def hotwords(self, permanent):
        self.last_report = {"enabled": self.config.get("enabled") is True,
                            "candidate_count": 0, "selected_hotwords": [],
                            "collection_ms": 0.0, "error": None}
        if not self.last_report["enabled"]:
            return permanent
        started = time.perf_counter()
        try:
            project_text = self.config.get("project_directory", "")
            project = Path(project_text).expanduser().resolve() if project_text else None
            db_text = self.config.get("database_path", "")
            db_path = Path(db_text) if db_text else Path(get_user_app_data_path()) / "vocabulary.db"
            db_path.parent.mkdir(parents=True, exist_ok=True)
            items, sources = collect(project)
            self.last_report["collection_ms"] = round((time.perf_counter() - started) * 1000, 2)
            self.last_report["sources"] = sources
            self.last_report["candidate_count"] = len({
                term.casefold() for _, text in items for term in candidates(text)
            })
            selected = rank(db_path, project, items, limit=30)[:30]
            merged = merge(permanent, selected)
            self.last_report["selected_hotwords"] = selected
            self.last_report["total_ms"] = round((time.perf_counter() - started) * 1000, 2)
            self.logger.info(
                "Dynamic vocabulary: collection_ms=%.2f total_ms=%.2f candidates=%d selected=%d",
                self.last_report["collection_ms"], self.last_report["total_ms"],
                self.last_report["candidate_count"], len(selected),
            )
            self.logger.debug("Dynamic vocabulary: sources=%s selected_hotwords=%s", sources, selected)
            return merged
        except Exception as exc:  # noqa: BLE001 - required fail-open boundary
            self.last_report["error"] = type(exc).__name__
            self.last_report["total_ms"] = round((time.perf_counter() - started) * 1000, 2)
            self.logger.warning("Dynamic vocabulary fallback: error=%s total_ms=%.2f",
                                self.last_report["error"], self.last_report["total_ms"])
            return permanent
